PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_customer" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "phone" varchar(20) NULL, "address" text NULL, "gender" varchar(10) NULL, "birth_date" date NULL);
CREATE TABLE IF NOT EXISTS "dashboard_meltedgold" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "weight_first" decimal NOT NULL, "weight" decimal NOT NULL, "purity" varchar(10) NOT NULL, "seller_name" varchar(100) NOT NULL, "seller_phone" varchar(20) NULL, "assay_office" varchar(100) NOT NULL, "date" date NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_partner" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(10) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "family" varchar(100) NOT NULL, "phone" varchar(20) NULL, "account_number" varchar(50) NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_retentioncampaign" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "campaign_type" varchar(20) NOT NULL, "message" text NOT NULL, "send_days_after_purchase" integer unsigned NOT NULL CHECK ("send_days_after_purchase" >= 0), "specific_date" date NULL, "loyalty_points" integer unsigned NULL CHECK ("loyalty_points" >= 0), "inactive_days" integer unsigned NULL CHECK ("inactive_days" >= 0), "active" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_test" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(20) NOT NULL, "date" date NOT NULL, "time" time NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_userprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(20) NOT NULL, "phone" varchar(15) NULL, "is_active" bool NOT NULL, "created" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_purchaseitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "invoice_id" bigint NOT NULL REFERENCES "dashboard_purchaseinvoice" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "dashboard_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_partnermoneytransaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_type" varchar(3) NOT NULL, "amount" decimal NOT NULL, "date" date NOT NULL, "note" text NULL, "partner_id" bigint NOT NULL REFERENCES "dashboard_partner" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_partnergoldtransaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_type" varchar(3) NOT NULL, "weight" decimal NOT NULL, "date" date NOT NULL, "note" text NULL, "partner_id" bigint NOT NULL REFERENCES "dashboard_partner" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_meltedgoldsale" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL, "weight" decimal NOT NULL, "date" date NOT NULL, "created_at" datetime NOT NULL, "customer_id" bigint NOT NULL REFERENCES "dashboard_customer" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_campaignlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "message" text NOT NULL, "sent_at" datetime NOT NULL, "status" varchar(20) NOT NULL, "campaign_id" bigint NOT NULL REFERENCES "dashboard_retentioncampaign" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" bigint NOT NULL REFERENCES "dashboard_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_customercrm" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "last_purchase" date NULL, "total_purchases" decimal NOT NULL, "loyalty_points" integer unsigned NOT NULL CHECK ("loyalty_points" >= 0), "customer_id" bigint NOT NULL UNIQUE REFERENCES "dashboard_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_account" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "code" varchar(20) NOT NULL UNIQUE, "type" varchar(20) NOT NULL, "created" datetime NOT NULL, "description" varchar(255) NULL, "parent_id" bigint NULL REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_invoice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number" varchar(50) NOT NULL UNIQUE, "time" time NOT NULL, "total_price" decimal NOT NULL, "profit_total" decimal NOT NULL, "customer_id" bigint NOT NULL REFERENCES "dashboard_person" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "date" date NULL);
CREATE TABLE IF NOT EXISTS "dashboard_journalentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "description" varchar(255) NULL, "related_purchase_id" bigint NULL REFERENCES "dashboard_purchaseinvoice" ("id") DEFERRABLE INITIALLY DEFERRED, "related_sale_id" bigint NULL REFERENCES "dashboard_invoice" ("id") DEFERRABLE INITIALLY DEFERRED, "date" date NULL);
CREATE TABLE IF NOT EXISTS "dashboard_meltedgoldtransaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_type" varchar(3) NOT NULL, "source" varchar(100) NULL, "destination" varchar(100) NULL, "weight" decimal NOT NULL, "date" date NOT NULL, "note" text NULL, "created_at" datetime NOT NULL, "melted_gold_id" bigint NOT NULL REFERENCES "dashboard_product" ("id") DEFERRABLE INITIALLY DEFERRED, "price_per_gram" decimal NOT NULL, "total_price" decimal NOT NULL, "price_per_mesghal" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_purchaseinvoice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number" varchar(30) NOT NULL UNIQUE, "date" date NOT NULL, "weight" decimal NOT NULL, "purity" varchar(10) NOT NULL, "price" decimal NOT NULL, "note" text NULL, "image" varchar(100) NULL, "created_at" datetime NOT NULL, "seller_id" bigint NOT NULL REFERENCES "dashboard_person" ("id") DEFERRABLE INITIALLY DEFERRED, "number_store" varchar(30) NOT NULL, "total_price" decimal NOT NULL, "labor" decimal NOT NULL, "type" varchar(10) NOT NULL, "pricemesghal" decimal NOT NULL, "laborprice" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_person" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(10) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "type_partner" varchar(20) NOT NULL, "phone" varchar(20) NULL, "note" text NULL, "account_number" varchar(50) NULL, "created_at" datetime NOT NULL, "birth_date" date NULL, "gender" varchar(10) NULL, "account_id" bigint NULL UNIQUE REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "store" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "dashboard_bankaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "account_number" varchar(50) NULL, "created_at" datetime NOT NULL, "account_id" bigint NULL UNIQUE REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "branch_name" varchar(100) NULL, "code" varchar(10) NULL UNIQUE, "iban" varchar(26) NULL, "name" varchar(100) NOT NULL, "note" text NULL, "card_number" varchar(50) NULL, "owner" varchar(100) NOT NULL, "balance" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_cashaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "code" varchar(10) NULL UNIQUE, "note" text NULL, "created_at" datetime NOT NULL, "account_id" bigint NULL UNIQUE REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "balance" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_expenseaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "code" varchar(10) NULL UNIQUE, "balance" decimal NOT NULL, "note" text NULL, "created_at" datetime NOT NULL, "account_id" bigint NULL UNIQUE REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_receipt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "amount" decimal NOT NULL, "note" varchar(255) NULL, "bank_account_id" bigint NOT NULL REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "journal_entry_id" bigint NULL UNIQUE REFERENCES "dashboard_journalentry" ("id") DEFERRABLE INITIALLY DEFERRED, "source_account_id" bigint NOT NULL REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "amount" decimal NOT NULL, "note" varchar(255) NULL, "bank_account_id" bigint NOT NULL REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "expense_id" bigint NOT NULL REFERENCES "dashboard_expenseaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "journal_entry_id" bigint NULL UNIQUE REFERENCES "dashboard_journalentry" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dashboard_journalitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "debit_money" decimal NOT NULL, "credit_money" decimal NOT NULL, "credit_gold" decimal NOT NULL, "description" varchar(255) NULL, "account_id" bigint NULL REFERENCES "dashboard_account" ("id") DEFERRABLE INITIALLY DEFERRED, "entry_id" bigint NOT NULL REFERENCES "dashboard_journalentry" ("id") DEFERRABLE INITIALLY DEFERRED, "bank_account_id" bigint NULL REFERENCES "dashboard_bankaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "bank_statement_ref" varchar(255) NULL, "reconciled" bool NOT NULL, "reconciled_date" date NULL, "debit_gold" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_invoiceitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "gold_price_per_gram" decimal NOT NULL, "labor_per_gram" decimal NOT NULL, "profit_percent" decimal NOT NULL, "profit_total" decimal NOT NULL, "weight" decimal NULL, "total" decimal NOT NULL, "invoice_id" bigint NOT NULL REFERENCES "dashboard_invoice" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" bigint NOT NULL REFERENCES "dashboard_product" ("id") DEFERRABLE INITIALLY DEFERRED, "gold_price_mesghal" decimal NOT NULL, "labor_price" decimal NOT NULL, "purity" varchar(10) NOT NULL);
CREATE TABLE IF NOT EXISTS "dashboard_product" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(10) NOT NULL UNIQUE, "name" varchar(200) NOT NULL, "category" varchar(50) NOT NULL, "weight" decimal NOT NULL, "description" text NULL, "quantity" integer unsigned NULL CHECK ("quantity" >= 0), "image" varchar(100) NULL, "purity" varchar(10) NOT NULL, "labor" decimal NULL, "created" datetime NOT NULL, "initial_weight" decimal NULL, "laborprice" decimal NULL, "price" decimal NULL, "barcode_image" text NULL);
DELETE FROM sqlite_sequence;
